import { atom, update } from 'claude-code'
import type { Register } from 'claude-code'

import { DEFAULTS } from './defaults.js'
import { SOUND_PACKS, doneLine, playEvent, soundsCommand } from './sounds.js'
import { ON_OFF, choices, suggest } from './autocomplete.js'

// Generated by scripts/build-plugins.mjs from the shared code in hooks/.
const prefsAtom = atom({ plugin: 'sound-packs', key: 'prefs' } as const, DEFAULTS, { shape: 'prefs-1' })

export const register: Register = on => {
  on('prompt.autocomplete', async ($, e, next) => {
    const mine = suggest(e, 'sounds', {
    first: [...choices(['classic', ...Object.keys(SOUND_PACKS)]), { name: 'voice', description: 'Spoken \"All done!\"' }, ...[{ name: 'list', description: 'Show every option' }, { name: 'off', description: 'Turn off' }]],
    next: { voice: [...ON_OFF, ...choices(['Samantha', 'Daniel', 'Karen', 'Moira', 'Tessa', 'Alex'])] },
  })
    if (mine === undefined) return next(e)
    const theirs = await next(e)
    return { suggestions: [...theirs.suggestions, ...mine] }
  })
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'sounds', description: 'Pick a sound pack or turn on the voice', argumentHint: '<pack> | list | off | voice on|off|<name>' })
    const stored = await $.store.get('prefs')
    await update($, prefsAtom, () => ({ ...DEFAULTS, ...(stored !== null && typeof stored === 'object' ? stored : {}) }))
    return next(e)
  })
  on('command.run', { command: 'sounds' }, async ($, e) => {
    const words = e.args.trim().split(/\s+/).filter(w => w !== '')
    const first = words[0]?.toLowerCase()
    const rest = words.slice(1).join(' ')
    return { text: await (first === 'voice' ? soundsCommand($, 'voice', words[1]?.toLowerCase(), words.slice(1).join(' ') === 'on' || words.slice(1).join(' ') === 'off' ? '' : words.slice(1).join(' '), '/sounds voice') : soundsCommand($, 'sounds', first, rest, '/sounds')) }
  })
  on('tool.call', async ($, e, next) => {
    if (e.tool === 'AskUserQuestion') void playEvent($, 'ask', 'I have a question for you.')
    const result = await next(e)
    if ('isError' in result && result.isError === true) void playEvent($, 'error')
    return result
  })
  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined && !e.isAborted && e.durationMs > 20_000) await playEvent($, 'done', doneLine(e.turnId))
    return result
  })
}
